-- PT110-S3-Q23. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT110-S3-Q23$batch12$ AND q.stimulus=$batch12$Societies in which value is measured primarily in financial terms invariably fragment into isolated social units. But since money is not the main measure of value in nonindustrial societies, they must tend in contrast to be socially unified.$batch12$ AND q.prompt=$batch12$The flawed reasoning in which one of the following is most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT110-S3-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT110-S3-Q23$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S3-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT110-S3-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Nonindustrial societies tend to be socially unified.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Societies that measure value mainly in money fragment. Nonindustrial societies don't measure value mainly in money.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Money-measure → fragment. Not money-measure, so the argument concludes the opposite: unified. That denies the trigger and then claims the reverse result.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A → B. Not A. So the opposite of B.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT110-S3-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This correctly says the rule doesn't apply to jackals and wolves. It's valid.$batch12$), ($batch12$B$batch12$, $batch12$This applies a "usually" rule to two specific places. A different flaw.$batch12$), ($batch12$C$batch12$, $batch12$This generalizes from insects to all arthropods, a part-to-whole flaw.$batch12$), ($batch12$D$batch12$, $batch12$Poets often use nonliteral language. Journalists aren't poets, so the argument concludes they always speak literally. Same move: deny the trigger, claim the opposite.$batch12$), ($batch12$E$batch12$, $batch12$This applies the rule in its own direction: sophisticated machines cause trouble, computers are sophisticated. No denial of the trigger.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT110-S3-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
